mapper.select:
SELECT TO_CHAR(sl.sale_date, 'YYYY-MM') AS "date", SUM(slg.total) AS "amountSale", SUM(slg.num * g.purchasing_price) AS "amountCost", SUM(slg.total) - SUM(slg.num * g.purchasing_price) AS "amountProfit" FROM t_sale_list_goods slg LEFT JOIN t_sale_list sl ON slg.sale_list_id = sl.id LEFT JOIN t_goods g ON slg.goods_id = g.id WHERE sl.state = 1
AND TO_CHAR(sl.sale_date, 'YYYY-MM') >= #{begin}
AND TO_CHAR(sl.sale_date, 'YYYY-MM') <= #{end}
GROUP BY TO_CHAR(sl.sale_date, 'YYYY-MM') ORDER BY TO_CHAR(sl.sale_date, 'YYYY-MM') ASC
